class AsyncQueue<T> {
  private items: T[] = [];  private waiters: ((v: T) => void)[] = [];
  take(): Promise<T> {                        // suspends the task, not a thread
    const item = this.items.shift();
    if (item !== undefined) return Promise.resolve(item);
    return new Promise(resolve => this.waiters.push(resolve));
  }
  put(value: T): void {
    const resolve = this.waiters.shift();     // change state first
    if (resolve) resolve(value); else this.items.push(value);
  }
}
